{
  "merge_policy": "auto",
  "environment": {
    "setup_commands": [
      "bun install --frozen-lockfile"
    ]
  },
  "checks": {
    "commands": [
      "./scripts/scan-secrets.sh",
      "bun run typecheck",
      "bun run synth",
      "bun run test"
    ],
    "secrets": []
  },
  "deploy": {
    "targets": [
      {
        "name": "release",
        "on": "merge",
        "commands": [
          "./scripts/release.sh"
        ]
      }
    ],
    "secrets": []
  },
  "tools": {
    "secrets": []
  },
  "agents": {
    "orchestrator": {
      "max_iterations": 100
    },
    "engineer": {
      "max_iterations": 200
    },
    "reviewer": {
      "max_iterations": 30
    }
  },
  "labels": {
    "in_progress": "atoma/in-progress",
    "sub_issue": "atoma/sub-issue",
    "launched": "atoma/launched"
  },
  "auto_triggers": [
    {
      "event": "issue_comment.created",
      "agent": "$dispatch_agent",
      "condition": "atoma:dispatch"
    }
  ],
  "governed_paths": [
    ".github/**",
    "scripts/**"
  ],
  "merge_gates": [
    {
      "reason": "This changes the code that decides what an agent may merge. Read it before merging: a weakening here would not be caught anywhere later.",
      "when": {
        "files_changed": [
          "src/domain/merge-readiness.ts",
          "src/domain/merge-gates.ts",
          "src/domain/path-patterns.ts",
          "src/lib/merge-signals.ts"
        ]
      }
    }
  ]
}

/**
 * config.ts — shared helper for reading .github/atoma/config.json. The one
 * canonical copy used by every script and MCP server in this repo.
 *
 * Resolved against `ATOMA_MACHINERY_ROOT` when that is set, and against the
 * working directory otherwise -- see `configPath()` for why a runner sets it.
 */
import { readFileSync } from "node:fs";
import { DEFAULT_GOVERNED_PATHS } from "../domain/merge-readiness.ts";
import {
  resolveDeclaredSecrets,
  SECRET_DESTINATIONS,
  type SecretDestinationName,
  type SecretsResolution,
} from "../domain/declared-secrets.ts";
import { resolveDeployTargets, type DeployTargetsResolution } from "../domain/deploy-targets.ts";
import { resolveMergeGates, type MergeGatesResolution } from "../domain/merge-gates.ts";
import { resolveAutoTriggers } from "../domain/auto-triggers.ts";
import type { AtomaConfig } from "./types.ts";

/**
 * Where this project's configuration is read from.
 *
 * `ATOMA_MACHINERY_ROOT` is set by `atoma-runner` to a checkout of the default
 * branch, and unset everywhere else. The difference matters on a pull request
 * run: that workspace is the pull request's own head, so reading configuration
 * from it would let a pull request decide how the run reviewing it behaves --
 * which agent, which iteration budget, which commands, which credentials.
 *
 * Unset resolves to the working directory, which is what every other caller
 * wants and what this did before.
 */
function configPath(): string {
  const root = process.env.ATOMA_MACHINERY_ROOT?.trim();
  return root ? `${root}/.github/atoma/config.json` : ".github/atoma/config.json";
}

let cached: AtomaConfig | undefined;

/** Load and parse config.json (cached after first read within a process). */
export function loadConfig(): AtomaConfig {
  if (!cached) {
    cached = JSON.parse(readFileSync(configPath(), "utf8")) as AtomaConfig;
  }
  return cached;
}

/**
 * The label each key means when `config.json` does not say.
 *
 * One place, because a default written at the call site is written at every call site: the
 * sub-issue label's fallback appeared in `sibling-check.ts` and in `mcp/github.ts`, the
 * launched one in `sibling-check.ts` and `dispatch_sub_agent.ts`, the in-progress one in
 * two scripts. Change the writer's and not the reader's and `countOpenSiblings` filters on
 * a label nothing applies, so the sibling count never reaches zero and the parent is never
 * dispatched — with every run green.
 */
export const DEFAULT_LABELS = {
  sub_issue: "atoma/sub-issue",
  launched: "atoma/launched",
  in_progress: "atoma/in-progress",
} as const;

/** A label key that has a default. */
export type LabelKey = keyof typeof DEFAULT_LABELS;

/**
 * Look up a label from the top-level `labels` section of config.json.
 *
 * The fallback comes from [`DEFAULT_LABELS`] rather than from the caller, so two callers
 * asking for the same label cannot disagree about what it is called.
 */
export function getLabel(key: LabelKey): string {
  return loadConfig().labels?.[key] ?? DEFAULT_LABELS[key];
}

/** Look up the top-level `merge_policy` from config.json. */
export function getMergePolicy(fallback = "manual"): string {
  return loadConfig().merge_policy ?? fallback;
}

/**
 * Branch an issue's work starts from and targets, or "" for the default branch.
 *
 * Empty is deliberately the normal answer: callers pass it straight to `gh`,
 * which falls back to the repository's default branch on its own, so a project
 * that never sets this needs no special case anywhere.
 */
export function getBaseBranch(fallback = ""): string {
  // The one reader here that tolerates a MISSING config.json. No config means no
  // base branch, which is the same answer as a config without the key, so
  // `create_pr` should not start failing over a setting whose absence is the
  // normal case. The others deliberately still throw: defaulting a merge policy
  // or a label because a file could not be read would act on a guess.
  //
  // Narrowed to ENOENT, having been a bare `catch`. That caught a config.json
  // that exists and will not parse as well — the one case where every other
  // reader in this file throws, and where this one quietly aimed `create_pr` at
  // the default branch instead. "The file is not there" and "the file is broken"
  // are different facts and only the first is ordinary.
  try {
    return loadConfig().base_branch?.trim() || fallback;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return fallback;
    throw error;
  }
}

/**
 * Default cross encoder for issue search.
 *
 * Multilingual, and chosen on measurement rather than on the language this
 * repository happens to be written in: on a Japanese corpus it reached 91% top-1
 * against 86% for the Japanese-specialised model it was compared with. A
 * multilingual default costs nothing here and is the only sensible default for
 * a template that ships to repositories in languages nobody here anticipated.
 *
 * This is the one model choice that changes the answer. Swapping the first
 * stage's model moved nothing; swapping this one moved top-1 from 27% to 91%.
 */
// Exported because the runner needs it too: it keys the model cache on the model
// name, and a fallback of its own would key on a different name than the one the
// server then loads -- so the cache would never hit and nothing would say why.
export const DEFAULT_RERANKER = "onnx-community/bge-reranker-v2-m3-ONNX";

/**
 * The cross encoder issue search ranks with.
 *
 * Configurable because the default was picked by measuring one repository, and
 * a repository in another language — or one that would rather not download 600MB
 * on the first search — should be able to say so.
 */
export function getRerankerModel(): string {
  return loadConfig().search?.reranker_model?.trim() || DEFAULT_RERANKER;
}

/**
 * Paths whose change makes a merge a person's to perform.
 *
 * Configurable because "how agents run here" is not the same set of files in
 * every repository — one that keeps its workflows generated from source has a
 * second place to name. An empty array in config.json is a deliberate choice to
 * turn the gate off, and is honoured; an absent key takes the default.
 */
export function getGovernedPaths(): readonly string[] {
  return loadConfig().governed_paths ?? DEFAULT_GOVERNED_PATHS;
}

/**
 * This project's conditional merge gates, validated.
 *
 * Problems come back rather than throwing, like `getDeployTargets()`, because the
 * caller turns them into a blocker: a gate that cannot be read must stop the
 * merge, and a thrown error at this depth would surface as a tool failure that
 * loses the verdict instead of reporting it.
 */
export function getMergeGates(): MergeGatesResolution {
  return resolveMergeGates(loadConfig().merge_gates);
}

// `getTriggerAgent` was here: it read which agent an unconditional `auto_triggers`
// entry routed an event to, and had exactly one caller -- `dispatchPrValidation`,
// asking who reviews a pull request.
//
// That was the coupling #486 removed. Which agent reviews is now a parameter the
// caller passes, because opening a pull request no longer starts anyone by itself.
// Nothing else ever asked this question, so the function went with the trigger.

// No `getDeclaredSecrets()` here on purpose, though every other setting has a
// reader in this file.
//
// The credential declaration is read from the default branch by
// `read_secret_names.ts`, which loads that file itself and refuses to guess a
// path. A convenience wrapper here would be a second route to the same answer,
// and the next caller would find it first.
//
// `configPath()` above now sends every other setting to the default branch too on
// a runner, which makes the two consistent -- but not interchangeable. That one
// resolves a path it was handed; this one resolves one from the environment. The
// separation is what keeps a missing `ATOMA_MACHINERY_ROOT` from silently
// downgrading a credential decision to the working tree.

/**
 * Commands that verify a change, in order.
 *
 * Empty means this project runs nothing through `atoma-check.yml`, which is the
 * normal state for a repository pointing `workflows.ci` at its own workflow.
 */
export function getCheckCommands(): readonly string[] {
  return loadConfig().checks?.commands?.filter((command) => command.trim() !== "") ?? [];
}

/**
 * This project's deployments, validated.
 *
 * Problems come back rather than throwing so the deploy workflow can report all
 * of them at once and fail, instead of deploying the targets that happened to
 * parse.
 */
export function getDeployTargets(): DeployTargetsResolution {
  return resolveDeployTargets(loadConfig().deploy?.targets);
}

/**
 * Look up one of this project's own workflow names from the `workflows` section.
 *
 * Lives in config.json rather than in a repository variable because it is
 * project configuration: versioned, reviewable in a pull request, and one fewer
 * thing to remember when setting a repository up. That only works because
 * config.json is yours — the documented upgrade deliberately does not overwrite
 * it, unlike everything else under `.github/atoma/`.
 */
export function getWorkflowName(kind: "ci" | "cd", fallback = ""): string {
  return (loadConfig().workflows?.[kind] ?? "").trim() || fallback;
}

/**
 * How many agent handoffs may happen with nobody else commenting.
 *
 * Returned raw for `resolveHandoffLimit` to interpret, rather than defaulted here.
 * The domain module owns what an absent, zero or nonsense value means, and it owns
 * the default that the escalation comment quotes back to a person -- two places
 * deciding that is how the old limit's message came to name a number that was not
 * the limit.
 */
export function getHandoffLimit(): unknown {
  return loadConfig().limits?.agent_handoffs;
}

/**
 * How many consecutive runs may change nothing before a person is asked.
 *
 * Raw, like the handoff limit above and for the same reason: `domain/progress.ts`
 * owns what an absent or nonsense value means, and owns the default the escalation
 * comment quotes back.
 */
export function getNoProgressLimit(): unknown {
  return loadConfig().limits?.runs_without_change;
}

/**
 * How many times one piece of work may rebuild its environment.
 *
 * Raw, for `resolveReloadLimit` to interpret. The domain module owns what absent,
 * zero and nonsense mean, and it owns the default the refusal message quotes back
 * to the agent -- two places deciding that is how the old handoff limit came to
 * name a number that was not the limit.
 */
export function getReloadLimit(): unknown {
  return loadConfig().limits?.environment_reloads;
}

/**
 * The raw `runs_on` a project declared for one of the two jobs that run its own
 * commands, or undefined.
 *
 * Raw for `resolveRunsOn` to interpret, like every other limit and setting here:
 * the domain module owns what a bad value means and owns the default, so one
 * fallback exists rather than two that can disagree.
 */
export function getRunsOn(field: "checks" | "deploy"): unknown {
  const config = loadConfig();
  return field === "checks" ? config.checks?.runs_on : config.deploy?.runs_on;
}

/**
 * types.ts — shared type definitions, the one canonical copy used by every
 * script and MCP server in this repo.
 */

// `AutoTrigger` belongs to `domain/auto-triggers.ts`, which owns the rules that
// give `condition` its meaning. It used to be declared here, in a file with no
// way to evaluate it — so the type listed three condition values while the
// matcher implemented two, and nothing connected the two lists.
//
// Re-exported so the many callers that import their config types from one place
// keep working. `domain/` is the definition; this is a doorway to it, not a
// second copy.
import type { AutoTrigger } from "../domain/auto-triggers.ts";

export type { AutoTrigger };

export interface AtomaConfig {
  merge_policy: "auto" | "manual" | string;
  /**
   * Branch an issue's work starts from and its pull request targets.
   *
   * Unset means the repository's default branch, which is what most projects
   * want and why this ships unset. It exists for the one arrangement the default
   * cannot express: keeping `main` as the default branch, for releases and for
   * what GitHub shows first, while agents' work accumulates somewhere else.
   *
   * Fixing a branching strategy here would be the wrong trade. Requiring `main`
   * shuts out projects with an integration branch; assuming one saddles every
   * other project with a branch it does not use.
   */
  base_branch?: string;
  /**
   * Paths whose change takes the merge away from an agent and gives it to a
   * person — workflows, runner scripts, agent definitions, tool configuration,
   * rulesets.
   *
   * Unset takes `DEFAULT_GOVERNED_PATHS`, the whole deployed `.github/` control
   * surface. Set it to add a repository's own — a template that generates its
   * workflows from source has a second place those live — or to hand a corner of
   * `.github/` back, which is better done by naming the parts you do want
   * governed than by trusting a shorter default. Set it to `[]` to turn the gate
   * off, which is a decision rather than an accident.
   *
   * A pattern is a literal path or a directory followed by `/**`.
   */
  governed_paths?: string[];
  /**
   * Conditions under which an agent must not merge, beyond what a path can say.
   *
   * `governed_paths` above is the special case: paths, and nothing else. This is
   * the general form — "only when a migration is ADDED", "only when the pull
   * request carries this label", "only when the title says BREAKING" — for the
   * situations a project knows about and Atoma could not have guessed.
   *
   * Same outcome as `governed_paths`: the agent reviews and reports, and a person
   * merges. Not a required status check, because a required check stops people too.
   *
   * ```json
   * "merge_gates": [
   *   {
   *     "reason": "新しいマイグレーションを含むため、人間が確認してください",
   *     "when": { "files_added": ["db/migrations/**"] }
   *   }
   * ]
   * ```
   *
   * Validated by `resolveMergeGates`; see `domain/merge-gates.ts` for the
   * condition set, why it is configuration rather than a script, and why a
   * misspelled condition is an error rather than a gate that quietly never fires.
   */
  merge_gates?: unknown;
  /**
   * What this project runs to verify a change, as commands.
   *
   * Commands and not a workflow file because an agent can write one and not the
   * other: GITHUB_TOKEN is refused on `.github/workflows/**` by identity, on
   * every path and branch. `atoma-check.yml` runs whatever is named here, so a
   * project's verification can be authored by an agent and reviewed as an
   * ordinary diff.
   *
   * Unset means this project verifies nothing through Atoma; point
   * `workflows.ci` at a workflow of your own instead.
   */
  checks?: {
    /** Run in order, stopping at the first failure. */
    commands?: string[];
    /** Repository secrets `atoma-check.yml` may reach. See `tools.secrets`. */
    secrets?: string[];
    /**
     * Which machine the checks run on. `"macos-latest"`, or a list of labels a
     * self-hosted runner must have — `["self-hosted", "linux", "gpu"]`.
     *
     * Unset takes `ubuntu-latest`. This was hardcoded and unreachable from here,
     * which made `atoma-check` unusable for a project that builds on macOS or needs
     * a licensed toolchain: fixing it meant editing `.github/workflows/**`, the one
     * place `GITHUB_TOKEN` cannot write, so neither an agent nor a workflow could,
     * and a hand-edited fork is overwritten by the next upgrade.
     *
     * One runner, however many labels — not several runners. Several would change
     * the check run's NAME (`atoma-check (ubuntu-latest)`), so the context the
     * ruleset requires would stop existing and every pull request would wait on a
     * check that never reports. See `domain/runner-label.ts`.
     */
    runs_on?: string | string[];
  };
  /**
   * What this project deploys, and which event deploys it.
   *
   * Validated by `resolveDeployTargets`. See `domain/deploy-targets.ts` for why
   * the trigger is configuration rather than the workflow's own `on:`.
   */
  deploy?: {
    targets?: unknown;
    /** Repository secrets `atoma-deploy.yml` may reach. See `tools.secrets`. */
    secrets?: string[];
    /**
     * Which machine the deployment runs on. Same form as `checks.runs_on`.
     *
     * One runner for the whole job, because the targets run in declared order and
     * stop at the first failure — that ordering is the contract, and a runner per
     * target would end it. A project that genuinely needs different machines for
     * different targets is asking for something else; see #437.
     */
    runs_on?: string | string[];
  };
  /** Settings for the tool servers an agent calls. */
  tools?: {
    /**
     * Repository secrets a run hands to the agent, for tool servers that talk to
     * something outside GitHub.
     *
     * Unset, and `[]`, mean the agent sees only the credentials the run needs to
     * work at all — which is the default and what most projects want. Naming one
     * here is a deliberate widening of what the agent can read, which is why it
     * lives in a versioned, reviewable file rather than in repository settings.
     *
     * Each entry is the name of a secret that already exists in the repository;
     * this declares which of them may travel, it does not create them. Validated
     * by `resolveToolSecrets` — a name the run already uses for itself, a
     * duplicate, or more than `TOOL_SECRET_SLOTS` of them fails the run with a
     * message rather than being quietly dropped.
     *
     * Nested under the feature that consumes it, rather than named for it at the
     * top level, because it is one of several destinations a credential can have
     * — these reach the agent's own process, and nothing else should.
     */
    secrets?: string[];
  };
  search?: {
    /**
     * Cross encoder used to rank issue search results.
     *
     * The one model choice that changes the answer: the first stage is BM25,
     * which has no model, and this decides the order of what it finds. Any
     * transformers.js-compatible sequence-classification model works.
     */
     reranker_model?: string;
  };
  /**
   * Bounds on how far a chain of agent runs may go before a person is asked.
   *
   * Separate from `agents.<name>.max_iterations`, and the difference is the unit:
   * that one bounds the tool-call loop inside ONE run and resets on every new run,
   * so every path that starts a run extends the budget. This bounds the chain of
   * runs itself.
   */
  limits?: {
    /**
     * How many times agents may hand work to each other with nobody else
     * commenting, before the chain stops and a person is asked.
     *
     * Counted from the target's comments rather than stored anywhere, so it
     * survives a re-dispatch — see `domain/dispatch-chain.ts`. Issue and pull
     * request count separately: opening a pull request is progress.
     *
     * Unset takes 5. That is chosen against a history where a person intervenes
     * often — the longest chain measured is three — so a repository running
     * autonomously will want a larger number, and one that wants tighter
     * supervision a smaller one. `0` means the default rather than "no handoffs";
     * turn `auto_triggers` off to say that.
     */
    agent_handoffs?: number;
    /**
     * How many consecutive agent runs may change nothing before the next
     * automatic handoff is withheld and a person is asked.
     *
     * "Changed nothing" means the run pushed no commit, opened no pull request and
     * merged none — read from what each result comment records about itself, not
     * from a counter. See `domain/progress.ts`.
     *
     * Unset takes 2. One run that changes nothing is ordinary: an agent that
     * investigated and reported did its job. Two in a row, with nothing else
     * happening between them, is the shape of an agent going round — and it fires
     * sooner than `agent_handoffs` while leaving a long piece of real work alone,
     * because length is not the thing being measured. `0` means the default.
     */
    runs_without_change?: number;
    /**
     * How many times one piece of work may rebuild its environment with
     * `atoma_env__reload_environment`, before the tool refuses.
     *
     * A reload re-runs `environment.setup_commands` as a privileged workflow step
     * and starts a NEW RUN — so `max_iterations` resets with it. Without a limit,
     * reloading is an unbounded extension of the iteration budget, which is why
     * #456 blocked the tool until there was one.
     *
     * Carried as a workflow input rather than counted from comments, unlike
     * `agent_handoffs`: a reload leaves no comment for a later run to count.
     *
     * Unset takes 3, borrowed from `CI_RETRY_LIMIT` for the same reason — enough
     * for a fix that needed another look, few enough that a stuck run reaches a
     * person quickly. `0` means the default; a project that wants no reloads at all
     * removes the `atoma_env` server from an agent's `mcp_servers`, which says so.
     */
    environment_reloads?: number;
  };
  environment?: {
    setup_commands?: string[];
  };
  agents?: Record<string, { max_iterations?: number }>;
  /**
   * Workflows of this project's own that Atoma should dispatch instead of the
   * shipped ones.
   *
   * Set these only when a pipeline cannot be expressed as `checks.commands` or
   * `deploy.targets` — a deployment approval gate, an unusual trigger, a job
   * needing permissions the shipped workflows do not declare. Otherwise leave
   * both unset: the default is `atoma-check.yml` / `atoma-deploy.yml`, which run
   * this project's configured commands and need no workflow authoring.
   */
  workflows?: {
    /** Put a required check on a pull request's head commit before merging. Defaults to `atoma-check.yml`. */
    ci?: string;
    /** Dispatched after a successful merge. Defaults to `atoma-deploy.yml`, which no-ops with no merge targets. */
    cd?: string;
  };
  labels?: {
    in_progress?: string;
    sub_issue?: string;
    launched?: string;
    [key: string]: string | undefined;
  };
  auto_triggers?: AutoTrigger[];
}

/** Minimal shape of `gh issue view --json author` (NOT the REST `.user.type` shape). */
export interface GhIssueAuthor {
  author?: {
    is_bot?: boolean;
    login?: string;
  };
}

export interface GhIssueSummary {
  number: number;
  title: string;
  state: string;
  labels?: { name: string }[];
}

export interface GhPrSummary {
  number: number;
  title: string;
  url: string;
}

import { describe, expect, test } from "bun:test";
import ts from "typescript";
import { readdirSync, readFileSync } from "node:fs";
import { configProblems, knownConfigKeys } from "../../src/domain/deliverable-integrity.ts";
import { CONDITION_KEYS, resolveMergeGates } from "../../src/domain/merge-gates.ts";

describe("config.json", () => {
  test("is valid and matches expected shape", async () => {
    const c = await Bun.file("src/atoma/config.json").json();
    expect(c.agents.orchestrator.max_iterations).toBe(100);
    expect(c.merge_policy).toBe("auto");
    expect(c.labels).toBeDefined();
  });

  // Gates are the project's own conditions, so the template ships none. A
  // default `db/migrations/**` would be a guess about somebody else's repository,
  // and a wrong one would block their merges on day one.
  test("the shipped template declares no merge gates", async () => {
    const c = await Bun.file("src/atoma/config.json").json();
    expect(c.merge_gates).toBeUndefined();
    expect(resolveMergeGates(c.merge_gates)).toEqual({ gates: [], problems: [] });
  });
});

// The condition set and the table documenting it are joined by nothing but two
// people writing the same words. A condition added in code and left out of the
// docs is unfindable; one documented and never implemented is worse, because
// someone writes it, it is rejected as unknown, and the docs said it existed.
describe("merge_gates documentation", () => {
  // The resolver's own list, not a copy of it. A copy meant adding a condition and
  // forgetting this array left it undocumented while both tests below still passed.
  const CONDITIONS = CONDITION_KEYS;

  test("every condition the code accepts appears in the customization guide", () => {
    const docs = readFileSync("docs/customization.md", "utf8");
    for (const condition of CONDITIONS) {
      expect(docs, `${condition} must be documented`).toContain(`\`${condition}\``);
    }
  });

  test("the code accepts every condition the guide documents", () => {
    // Read back through the resolver rather than against a second list: a
    // documented condition that the resolver rejects reports itself here.
    for (const condition of CONDITIONS) {
      const value = condition === "title_matches" ? "^x" : ["db/migrations/**"];
      const { gates, problems } = resolveMergeGates([{ reason: "r", when: { [condition]: value } }]);
      expect(problems, condition).toEqual([]);
      expect(gates, condition).toHaveLength(1);
    }
  });

  test("the reviewer knows what to do with the blockers a gate produces", () => {
    const reviewer = readFileSync("src/atoma/agent-definitions/reviewer.md", "utf8");
    for (const kind of ["merge-gate", "gate-config-invalid"]) {
      expect(reviewer, `${kind} must be in the reviewer's blocker table`).toContain(`\`${kind}\``);
    }
  });
});

/**
 * config.json's recognised keys, in the type and at run time.
 *
 * `AtomaConfig` in `lib/types.ts` is the definition and `CONFIG_SCHEMA` in
 * `domain/deliverable-integrity.ts` is the runtime mirror, because an interface is
 * erased before anything can consult it. Two lists of the same fact — which is
 * exactly what `validate_deliverable.ts` exists to catch in an adopter's config, so
 * it had better not be uncheckable here.
 *
 * The interface is the authority, and this reads it with TypeScript's own parser
 * rather than with a regular expression. A regex was tried and is not good enough:
 * the nested members are indented inconsistently in that file (one is at five
 * spaces), `Record<string, {...}>` has to be understood rather than matched, and an
 * index signature means something specific — any name is legal here — that a line
 * pattern cannot distinguish from a property.
 *
 * Drift in either direction is a real failure. A key added to the type and not to
 * the schema is reported to an adopter as a typo, for a setting the code reads. One
 * added to the schema and not the type is accepted and read by nothing.
 */
describe("config.json's recognised keys", () => {
  /** `Record<string, X>`'s value type, or undefined when `type` is not one. */
  function recordValueType(type: ts.TypeNode | undefined, source: ts.SourceFile): ts.TypeNode | undefined {
    if (!type || !ts.isTypeReferenceNode(type)) return undefined;
    if (type.typeName.getText(source) !== "Record") return undefined;
    return type.typeArguments?.[1];
  }

  /** Dotted paths under `path`, with `*` for a level where any name is legal. */
  function descend(type: ts.TypeNode | undefined, path: string, source: ts.SourceFile, out: string[]): void {
    if (!type) return;
    if (ts.isTypeLiteralNode(type)) {
      if (type.members.some((member) => ts.isIndexSignatureDeclaration(member))) out.push(`${path}.*`);
      for (const member of type.members) {
        if (!ts.isPropertySignature(member) || !member.name) continue;
        const child = `${path}.${member.name.getText(source)}`;
        out.push(child);
        descend(member.type, child, source, out);
      }
      return;
    }
    const value = recordValueType(type, source);
    if (value) {
      out.push(`${path}.*`);
      descend(value, `${path}.*`, source, out);
    }
  }

  function keysFromTheInterface(): string[] {
    const file = "src/lib/types.ts";
    const source = ts.createSourceFile(file, readFileSync(file, "utf8"), ts.ScriptTarget.Latest, true);
    const declaration = source.statements.find(
      (statement): statement is ts.InterfaceDeclaration =>
        ts.isInterfaceDeclaration(statement) && statement.name.text === "AtomaConfig",
    );
    expect(declaration, "AtomaConfig is no longer an interface in src/lib/types.ts").toBeDefined();

    const out: string[] = [];
    for (const member of declaration!.members) {
      if (!ts.isPropertySignature(member) || !member.name) continue;
      const name = member.name.getText(source);
      out.push(name);
      descend(member.type, name, source, out);
    }
    return out.sort();
  }

  test("the runtime schema and the interface name the same keys", () => {
    expect(knownConfigKeys()).toEqual(keysFromTheInterface());
  });

  /**
   * The keys a person can actually set: the leaves of the schema, minus the levels
   * where any name is legal.
   *
   * A parent is not settable on its own — writing `"checks": {}` configures nothing
   * — and `labels.*` is not a key at all, it is permission to invent one. So
   * neither belongs in a list an adopter reads.
   */
  function settableKeys(): string[] {
    const all = knownConfigKeys();
    return all
      .filter((key) => !all.some((other) => other.startsWith(`${key}.`)))
      .filter((key) => !key.endsWith("*"))
      .sort();
  }

  /** The first backticked token of each bullet in the `config.json` contract section. */
  function documentedKeys(): string[] {
    const docs = readFileSync("docs/customization.md", "utf8").replace(/\r\n/g, "\n");
    const start = docs.indexOf("## `config.json` contract");
    expect(start, "the config.json contract section is gone from docs/customization.md").toBeGreaterThan(-1);
    // Bounded at the next heading of any level: the subsections after it carry
    // bullet lists of their own, and those are not config keys.
    const offset = docs.slice(start + 1).search(/\n#{2,3} /);
    const section = docs.slice(start, offset === -1 ? undefined : start + 1 + offset);

    const keys: string[] = [];
    for (const line of section.split("\n")) {
      const match = /^- `([^`]+)`/.exec(line);
      // `<name>` is how the docs write a level where any name is legal, and `*` is
      // how the schema writes it. One bullet, one key: a bullet may go on to
      // mention the fields an entry takes, and those are not top-level keys.
      if (match?.[1]) keys.push(match[1].replace("<name>", "*"));
    }
    return keys.sort();
  }

  /**
   * The list an adopter writes config.json from, held to the schema that judges it.
   *
   * A fourth copy of the same fact lived here — the interface, the runtime schema,
   * the readers in `lib/config.ts`, and this list — and the drift is worse than
   * useless in one specific direction: a key documented but not read is one an
   * adopter writes, and `validate_deliverable.ts` then fails their pull request for
   * following the documentation.
   */
  test("the customization guide lists every settable key, and no others", () => {
    expect(documentedKeys()).toEqual(settableKeys());
  });

  // The walk above finds nothing if the interface is renamed or the file moves, and
  // an empty list would compare equal to an empty schema.
  test("the walk found something", () => {
    expect(keysFromTheInterface().length).toBeGreaterThan(10);
  });

  // Every key the shipped config sets has to be one the schema recognises, or the
  // template validates as broken on the first adoption.
  test("the shipped config.json declares only recognised keys", async () => {
    const config = await Bun.file("src/atoma/config.json").json();
    expect(
      configProblems({
        config,
        agentNames: readdirSync("src/atoma/agent-definitions")
          .filter((file) => file.endsWith(".md"))
          .map((file) => file.slice(0, -".md".length)),
        workflowFiles: readdirSync("dist/.github/workflows"),
      }),
    ).toEqual([]);
  });
});

{
  "merge_policy": "auto",
  "environment": {
    "setup_commands": []
  },
  "checks": {
    "commands": [],
    "secrets": []
  },
  "deploy": {
    "targets": [],
    "secrets": []
  },
  "tools": {
    "secrets": []
  },
  "agents": {
    "orchestrator": {
      "max_iterations": 100
    },
    "engineer": {
