/**
 * deliverable-integrity.ts — whether the `.github/atoma/` a pull request would
 * merge is internally consistent, decided from its content and nothing else.
 *
 * ## What this is for
 *
 * A name in configuration that resolves to nothing is the one class of defect
 * this project keeps producing and cannot see. `mcp_servers: [filesystem]` with
 * no `filesystem` in tools.yaml aborts the whole run before a single server
 * starts; `agents.enginer` sets an iteration budget for nobody; an
 * `auto_triggers` entry that fails validation resolves the WHOLE list to empty,
 * so every trigger stops firing. Each of those is silent at merge time and
 * surfaces on whoever triggers the next run.
 *
 * ## What it deliberately does not do
 *
 * No new validator is written here. Every rule below is either a reference that
 * either resolves or does not, or a call to a resolver that already exists and
 * already runs — `resolveAutoTriggers`, `resolveMergeGates`,
 * `resolveDeployTargets`, `resolveDeclaredSecrets`. All four are pure functions of
 * a config value, and all four currently run too late to matter: at merge time, at
 * deploy time, when a credential is handed out. Running them at pull-request time
 * adds no opinion, it moves an existing one earlier.
 *
 * Anything that needs a run to find out is out of scope and stays out. Whether a
 * `checks.commands` entry passes, whether a deploy target's shell works, whether a
 * model answers — none of that is knowable from the files, and pretending
 * otherwise would make this a second, worse CI.
 *
 * ## Where the agent definitions and tools.yaml are checked
 *
 * Not here. `atoma validate --agent-def X.md --tools-file tools.yaml` already
 * checks the parse, `mcp_servers` against the tools file, `knows_about` targets,
 * `callable_by` values, `extra_body` reserved keys and the hook paths the tools
 * file names — using the same code the run itself uses. `validate_deliverable.ts`
 * calls it once per agent definition rather than reimplementing any of that in
 * TypeScript, which would be the same facts in two languages.
 *
 * So this module owns exactly one format: config.json, which is delivery's own and
 * which the core has never heard of.
 */
import { resolveAutoTriggers } from "./auto-triggers.ts";
import { resolveDeclaredSecrets, SECRET_DESTINATIONS } from "./declared-secrets.ts";
import { resolveDeployTargets } from "./deploy-targets.ts";
import { resolveMergeGates } from "./merge-gates.ts";
import { DEFAULT_CD_WORKFLOW, DEFAULT_CI_WORKFLOW } from "./shipped-workflows.ts";

/**
 * One section of config.json, or `null` for a value whose interior config.json
 * does not describe.
 *
 * `null` is not "anything goes" — it is "the key is recognised and something else
 * decides what may be in it". `auto_triggers`, `merge_gates` and `deploy.targets`
 * are all `null` here and all validated below by their own resolver.
 */
interface Section {
  /** Keys recognised by name. */
  readonly children?: Readonly<Record<string, Section | null>>;
  /**
   * Present when any name is legal at this level, and the shape each one takes.
   *
   * `agents` is the case that needs it: the names are the project's agents, which
   * this file cannot know. `labels` has both — three names with meanings and an
   * index signature for a project's own.
   */
  readonly anyName?: Section | null;
}

/**
 * config.json's recognised keys.
 *
 * `AtomaConfig` in `lib/types.ts` is the definition; this is the runtime mirror,
 * because an interface is erased before anything can consult it.
 * `config-contract.test.ts` extracts the interface's keys with TypeScript's own
 * parser and asserts this tree matches exactly — so a key added to the type and
 * not to this tree fails a test rather than being reported to an adopter as
 * unrecognised.
 *
 * That test is the whole reason this is safe to have. Without it the two lists
 * drift in the worst direction: a key the code reads, reported here as a typo.
 */
const CONFIG_SCHEMA: Section = {
  children: {
    merge_policy: null,
    base_branch: null,
    governed_paths: null,
    merge_gates: null,
    auto_triggers: null,
    checks: { children: { commands: null, secrets: null, runs_on: null } },
    deploy: { children: { targets: null, secrets: null, runs_on: null } },
    tools: { children: { secrets: null } },
    search: { children: { reranker_model: null } },
    environment: { children: { setup_commands: null } },
    workflows: { children: { ci: null, cd: null } },
    agents: { anyName: { children: { max_iterations: null } } },
    limits: { children: { agent_handoffs: null, environment_reloads: null, runs_without_change: null } },
    labels: { children: { in_progress: null, sub_issue: null, launched: null }, anyName: null },
  },
};

/**
 * Every key the schema recognises, as dotted paths, with `*` for a level where
 * any name is legal.
 *
 * Exported for `config-contract.test.ts`, which compares this against the same
 * projection of the `AtomaConfig` interface.
 */
export function knownConfigKeys(): string[] {
  const paths: string[] = [];
  const walk = (section: Section, prefix: string): void => {
    for (const [name, child] of Object.entries(section.children ?? {})) {
      const path = `${prefix}${name}`;
      paths.push(path);
      if (child) walk(child, `${path}.`);
    }
    if (section.anyName !== undefined) {
      const path = `${prefix}*`;
      paths.push(path);
      if (section.anyName) walk(section.anyName, `${path}.`);
    }
  };
  walk(CONFIG_SCHEMA, "");
  return paths.sort();
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** Keys present in `value` that the schema does not recognise, as dotted paths. */
function unknownKeys(value: unknown, section: Section, prefix: string): string[] {
  if (!isRecord(value)) return [];
  const unknown: string[] = [];
  for (const [name, child] of Object.entries(value)) {
    const path = `${prefix}${name}`;
    const declared = section.children?.[name];
    if (declared !== undefined) {
      if (declared) unknown.push(...unknownKeys(child, declared, `${path}.`));
      continue;
    }
    if (section.anyName !== undefined) {
      if (section.anyName) unknown.push(...unknownKeys(child, section.anyName, `${path}.`));
      continue;
    }
    unknown.push(path);
  }
  return unknown;
}

/**
 * What the deliverable's own files say about itself, gathered by the caller.
 *
 * Passed in rather than read here so this module stays a pure function of its
 * input and the whole rule set is testable without a directory on disk.
 */
export interface DeliverableFacts {
  /** Parsed config.json. */
  readonly config: unknown;
  /** Agent names available, one per `agent-definitions/<name>.md`. */
  readonly agentNames: readonly string[];
  /** File names present in `.github/workflows/`, e.g. `atoma-check.yml`. */
  readonly workflowFiles: readonly string[];
}

/** The agent an `auto_triggers` entry names, or "" when it names one at run time. */
function triggerAgent(agent: string): string {
  // `$dispatch_agent` and anything else `$`-prefixed is filled in from the event
  // — see `match_trigger.ts`. There is no name here to check against a file.
  return agent.startsWith("$") ? "" : agent;
}

/**
 * Every way this config.json is inconsistent with the deliverable around it.
 *
 * Returns all of them rather than the first, so one pull request reports
 * everything an agent has to fix instead of one thing per round trip.
 */
export function configProblems(facts: DeliverableFacts): string[] {
  const problems: string[] = [];
  const { config, agentNames, workflowFiles } = facts;

  if (!isRecord(config)) {
    return ["`config.json` must be a JSON object."];
  }

  // ── keys nothing reads ────────────────────────────────────────────────────
  //
  // The failure this catches is total silence. A misspelled `governed_path` is
  // not an error anywhere: the reader asks for `governed_paths`, gets undefined,
  // takes the default, and the setting the author wrote has no effect at all.
  for (const key of unknownKeys(config, CONFIG_SCHEMA, "").sort()) {
    problems.push(`\`${key}\` in config.json is not a setting Atoma reads. Check the spelling.`);
  }

  // ── the four resolvers, run early ─────────────────────────────────────────
  const triggers = resolveAutoTriggers(config.auto_triggers);
  problems.push(...triggers.problems);
  problems.push(...resolveMergeGates(config.merge_gates).problems);

  // `deploy` and `checks` are read for their SHAPE only, which is not the same as
  // taking direction from them. #414 rules out letting an adopter's pipeline
  // configure this validation — running their commands, deciding what to check
  // from their config. Asking whether `deploy.targets` is a well-formed array of
  // targets is this deliverable validating itself, and the alternative is what
  // happens today: `resolveDeployTargets` reports it after the merge, from the
  // deploy run, where nobody is watching.
  const deploy = isRecord(config.deploy) ? config.deploy : {};
  problems.push(...resolveDeployTargets(deploy.targets).problems);

  const checks = isRecord(config.checks) ? config.checks : {};
  const tools = isRecord(config.tools) ? config.tools : {};
  problems.push(...resolveDeclaredSecrets(tools.secrets, SECRET_DESTINATIONS.tools).problems);
  problems.push(...resolveDeclaredSecrets(checks.secrets, SECRET_DESTINATIONS.checks).problems);
  problems.push(...resolveDeclaredSecrets(deploy.secrets, SECRET_DESTINATIONS.deploy).problems);

  // ── names that have to resolve to a file ──────────────────────────────────
  //
  // Only checked when the definitions were found at all. An empty set means the
  // directory was not there, and reporting every agent as missing would bury the
  // one problem that matters under noise.
  if (agentNames.length > 0) {
    const known = new Set(agentNames);
    const available = [...known].sort().join(", ");

    for (const trigger of triggers.triggers) {
      const agent = triggerAgent(trigger.agent);
      if (agent && !known.has(agent)) {
        problems.push(
          `\`auto_triggers\` routes \`${trigger.event}\` to '${agent}', which has no ` +
            `agent-definitions/${agent}.md. The event would dispatch a run that cannot start. ` +
            `Available: ${available}`,
        );
      }
    }

    if (isRecord(config.agents)) {
      for (const name of Object.keys(config.agents).sort()) {
        if (!known.has(name)) {
          problems.push(
            `\`agents.${name}\` configures an agent with no agent-definitions/${name}.md, ` +
              `so nothing reads it. Available: ${available}`,
          );
        }
      }
    }
  } else {
    problems.push("No agent definitions were found. `.github/atoma/agent-definitions/*.md` is empty or missing.");
  }

  // ── the two workflows a dispatch names ────────────────────────────────────
  //
  // A name that is not a file fails at `gh workflow run`, which is the moment
  // there is no longer anywhere to report it: the CI dispatch fails inside
  // `validate_pull_request.ts` and the pull request loses its required check with
  // no agent scheduled after it.
  if (workflowFiles.length > 0) {
    const present = new Set(workflowFiles);
    const workflows = isRecord(config.workflows) ? config.workflows : {};
    for (const [kind, fallback] of [
      ["ci", DEFAULT_CI_WORKFLOW],
      ["cd", DEFAULT_CD_WORKFLOW],
    ] as const) {
      const configured = typeof workflows[kind] === "string" ? (workflows[kind] as string).trim() : "";
      const effective = configured || fallback;
      if (!present.has(effective)) {
        problems.push(
          `\`workflows.${kind}\` resolves to '${effective}', which is not a file in .github/workflows/. ` +
            (configured ? "Check the name." : "The shipped default is missing from this repository."),
        );
      }
    }
  }

  // ── labels ───────────────────────────────────────────────────────────────
  //
  // A label configured as "" is applied as "" and matched as "", so a filter on it
  // finds nothing and the count that gates a parent's dispatch never reaches zero.
  if (isRecord(config.labels)) {
    for (const [key, value] of Object.entries(config.labels)) {
      if (typeof value !== "string" || value.trim() === "") {
        problems.push(`\`labels.${key}\` must be a non-empty label name.`);
      }
    }
  }

  return problems;
}

/**
 * auto-triggers.ts — validates `auto_triggers`, and says which of them an event
 * actually selects.
 *
 * `docs/customization.md` states the rule this module exists to keep, in the
 * section on merge gates:
 *
 *   **Mistakes are errors, not silence.** A misspelled condition, a pattern this
 *   matcher cannot honour, a gate with no conditions at all: each stops the merge
 *   and says why, instead of producing a gate that never fires.
 *
 * `auto_triggers` was the one list that did the opposite, and did it in the more
 * dangerous direction. `match_trigger.ts` asked "is the condition one I know, and
 * does it fail?" — so a condition it did not know was not a condition that never
 * fires, it was a trigger that fires **unconditionally**. A `non_draft` mistyped
 * as `nondraft` dispatched an agent onto every draft pull request, and the
 * config's author had every reason to believe the opposite.
 *
 * Same `{values, problems}` shape as `resolveMergeGates` and
 * `resolveDeployTargets`, and the same all-or-nothing rule: a list with any
 * problem resolves to no triggers at all. A partly-honoured trigger list is one
 * that dispatches some agents and silently not others.
 */
/**
 * One `auto_triggers` entry: an event, the agent it selects, and optionally a
 * condition narrowing when it applies.
 *
 * Defined here rather than in `lib/types.ts`, where it used to live, because
 * `domain/` may not import from `lib/` and the rules that give `condition` its
 * meaning are in this file. `AtomaConfig` imports it back.
 */
export interface AutoTrigger {
  event: string;
  agent: string;
  condition?: TriggerCondition;
}

/**
 * How a condition is answered.
 *
 * `runtime` conditions are evaluated per event from the workflow's own context.
 * `elsewhere` names the one condition that is deliberately never answered here:
 * `atoma:dispatch` marks the entry that documents the delivery system's own
 * comment marker, which `atoma-manual-comment.yml` parses directly out of the
 * comment body. It is a legitimate value and it must never select an agent from
 * this matcher.
 *
 * That distinction used to be carried by an unrelated accident. The shipped
 * config pairs `atoma:dispatch` with `agent: "$dispatch_agent"`, and the matcher
 * skips any agent beginning with `$` — so the entry was passed over for the
 * wrong reason, and writing the same condition beside a real agent name would
 * have dispatched on every comment.
 */
export type ConditionKind = "runtime" | "elsewhere";

/**
 * One entry per condition, carrying what it means.
 *
 * The `kind` and the matcher were separate: this record listed the legal names and
 * tagged them, and a `switch` elsewhere in the file re-listed the same names with the
 * behaviour. Nothing read the tag at all — so the record documented a distinction the
 * switch re-implemented by hand as `case "atoma:dispatch": return false`.
 *
 * Adding a fourth condition here and forgetting the switch arm was silent in the worst
 * direction: `resolveAutoTriggers` accepts the config, `applies` falls through to
 * `default: false`, and the trigger never fires. That is the failure this module's header
 * says it exists to prevent, pointing the other way from the bug it was written for.
 *
 * With the matcher in the entry there is no switch to forget, and a missing one is a type
 * error.
 */
interface ConditionSpec {
  kind: ConditionKind;
  /** Whether this condition holds for the event in hand. */
  matches: (context: TriggerContext) => boolean;
}

export const TRIGGER_CONDITIONS: Readonly<Record<string, ConditionSpec>> = {
  changes_requested: {
    kind: "runtime",
    matches: (context) => context.reviewState === "changes_requested",
  },
  non_draft: {
    kind: "runtime",
    matches: (context) => context.isDraft !== true,
  },
  "atoma:dispatch": {
    kind: "elsewhere",
    // Answered by `atoma-manual-comment.yml`, which reads the marker out of the comment
    // body. Never selects an agent here — which is what `elsewhere` means, now said once.
    matches: () => false,
  },
};

/** The condition names a config file may use, for messages and for the type. */
export type TriggerCondition = keyof typeof TRIGGER_CONDITIONS;

export interface AutoTriggerResolution {
  triggers: AutoTrigger[];
  problems: string[];
}

const KNOWN = Object.keys(TRIGGER_CONDITIONS).sort();

function readTrigger(raw: unknown, where: string, problems: string[]): AutoTrigger | undefined {
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
    problems.push(`${where}: each entry must be an object with \`event\` and \`agent\`.`);
    return undefined;
  }
  const entry = raw as Record<string, unknown>;

  const unknownKeys = Object.keys(entry).filter((key) => !["event", "agent", "condition"].includes(key));
  if (unknownKeys.length > 0) {
    problems.push(`${where}: unknown key(s) ${unknownKeys.join(", ")}; expected event, agent, condition.`);
  }

  if (typeof entry.event !== "string" || entry.event.trim() === "") {
    problems.push(`${where}: \`event\` must be a non-empty string, e.g. "pull_request.opened".`);
  }
  if (typeof entry.agent !== "string" || entry.agent.trim() === "") {
    problems.push(`${where}: \`agent\` must be a non-empty string.`);
  }

  if (entry.condition !== undefined) {
    if (typeof entry.condition !== "string") {
      problems.push(`${where}: \`condition\` must be a string; found ${JSON.stringify(entry.condition)}.`);
    } else if (!(entry.condition in TRIGGER_CONDITIONS)) {
      problems.push(
        `${where}: unknown condition "${entry.condition}". Known conditions are ${KNOWN.join(", ")}. ` +
          `An unrecognised condition used to be ignored, which made the trigger fire every time instead of never.`,
      );
    }
  }

  if (typeof entry.event !== "string" || typeof entry.agent !== "string") return undefined;
  return {
    event: entry.event,
    agent: entry.agent,
    ...(typeof entry.condition === "string" ? { condition: entry.condition as AutoTrigger["condition"] } : {}),
  };
}

/** Validate the whole list. Any problem resolves to no triggers. */
export function resolveAutoTriggers(raw: unknown): AutoTriggerResolution {
  if (raw === undefined) return { triggers: [], problems: [] };
  if (!Array.isArray(raw)) {
    return { triggers: [], problems: ["`auto_triggers` must be an array of {event, agent, condition?} objects."] };
  }

  const problems: string[] = [];
  const triggers: AutoTrigger[] = [];
  raw.forEach((entry, index) => {
    const trigger = readTrigger(entry, `auto_triggers[${index}]`, problems);
    if (trigger) triggers.push(trigger);
  });

  return problems.length > 0 ? { triggers: [], problems } : { triggers, problems };
}

/** What the workflow knows about the event being routed. */
export interface TriggerContext {
  /** `<event_name>.<action>`, e.g. `pull_request.synchronize`. */
  event: string;
  /** The review state, when this is a `pull_request_review` event. */
  reviewState?: string;
  /** Whether the pull request is a draft. */
  isDraft?: boolean;
}

/**
 * The agent this event selects, or "" for none.
 *
 * Reads as "does this entry apply?", not as "do I know a reason to skip it?" —
 * which is the inversion that made an unknown condition fire. By the time this
 * runs, `resolveAutoTriggers` has already rejected unknown conditions, so the
 * `default` arm below is unreachable through the normal path; it is written
 * anyway, and it refuses, because the safe answer to a condition nobody can
 * evaluate is not to dispatch an agent.
 */
export function selectTriggerAgent(triggers: readonly AutoTrigger[], context: TriggerContext): string {
  for (const trigger of triggers) {
    if (trigger.event !== context.event) continue;
    // `$`-prefixed agents are placeholders that document a path handled by
    // another workflow, never a name to dispatch.
    if (trigger.agent.startsWith("$")) continue;
    if (!applies(trigger.condition, context)) continue;
    return trigger.agent;
  }
  return "";
}

/**
 * Whether a trigger's condition holds.
 *
 * An absent condition applies always — that is what "no condition" means. An unknown one
 * never does, and cannot arrive here anyway: `resolveAutoTriggers` rejects it with a
 * problem naming the legal values, which is the whole reason this is not the place that
 * decides what is legal.
 */
function applies(condition: string | undefined, context: TriggerContext): boolean {
  if (condition === undefined) return true;
  return TRIGGER_CONDITIONS[condition]?.matches(context) ?? false;
}

/**
 * merge-gates.ts — conditions under which an agent must not merge, declared by
 * the project rather than hardcoded here.
 *
 * ## Why this is not a required status check
 *
 * A required check stops everyone. The thing wanted here stops only the agent:
 * "a pull request that adds a database migration is a person's to merge" does not
 * mean the merge is forbidden, it means the judgement is not an agent's to make.
 * Branch protection cannot express that, because it does not know who is merging.
 *
 * `governed_paths` already has exactly this property and is the model. It says
 * "changes under `.github/**` fall to a person", the agent reviews and reports,
 * and a person merges. What it lacks is expressiveness: it matches paths and
 * nothing else, so `db/migrations/**` is sayable but "only when a migration is
 * ADDED" is not. These gates are that generalisation.
 *
 * ## Why declarative rather than a script
 *
 * The first proposal was a script per gate, spawned like `tools.yaml`'s
 * `before_tool` hook, with the exit code as the verdict. It is more expressive --
 * a script can read a migration and notice it drops a production table, which no
 * amount of configuration can.
 *
 * It is also the one decision here that is hard to take back, and it buys that
 * expressiveness with four new failure modes: a timeout, a crash whose default
 * has to be chosen, a program that must itself be read from the machinery rather
 * than from the pull request under review, and arbitrary code on the path that
 * decides whether that code may merge. Configuration has none of those. It is
 * read from `config.json`, which `loadConfig()` already resolves under
 * `ATOMA_MACHINERY_ROOT`, so a pull request cannot weaken the gate judging it --
 * for free, with nothing to plumb.
 *
 * So: conditions now, and a script escape hatch left unbuilt until a real case
 * needs one. The shape here does not stand in the way of adding it -- a gate is
 * an object with a `reason`, and a `run` key alongside `when` would be additive.
 *
 * ## Why unknown keys are an error
 *
 * A typo in `files_added` matches nothing, and a gate that matches nothing looks
 * identical to a gate that was never needed. Nobody finds out until the merge
 * they wanted stopped goes through quietly. `DEFAULT_GOVERNED_PATHS` carries the
 * same lesson from the other direction: an enumeration that silently omitted
 * `.github/scripts/` let an agent merge changes to its own limits. Silence is the
 * failure mode to design against, so every key is checked and anything
 * unrecognised is reported.
 */
import { pathMatches, pathPatternProblem } from "./path-patterns.ts";

/**
 * What happened to one file in a pull request.
 *
 * Three states, not GitHub's seven. `copied` is an addition, `changed` is a
 * modification, and a rename is reported by the adapter as an addition at the new
 * path AND a removal at the old one -- otherwise `git mv` into `db/migrations/`
 * would walk past a `files_added` gate while plainly adding a migration.
 */
export type FileStatus = "added" | "removed" | "modified";

export interface ChangedFile {
  readonly path: string;
  readonly status: FileStatus;
}

/**
 * When a gate applies. Conditions AND within a gate, gates OR across the list --
 * so one gate is one situation, and more situations are more gates.
 *
 * An absent condition is not a condition. Empty arrays and an empty
 * `titleMatches` mean "this gate does not constrain that", which is why a gate
 * with no conditions at all is rejected rather than read as "always".
 */
export interface MergeGateConditions {
  readonly filesAdded: readonly string[];
  readonly filesRemoved: readonly string[];
  readonly filesModified: readonly string[];
  /** Added, removed or modified -- the union, and what `governed_paths` matches on. */
  readonly filesChanged: readonly string[];
  /** Matches when the pull request carries any one of these labels. */
  readonly labels: readonly string[];
  /** Case-insensitive regular expression source, or "" for no title condition. */
  readonly titleMatches: string;
}

export interface MergeGate {
  /** Said to a person, so it is theirs to write. Relayed verbatim in the blocker. */
  readonly reason: string;
  readonly when: MergeGateConditions;
}

export interface MergeGatesResolution {
  readonly gates: readonly MergeGate[];
  readonly problems: readonly string[];
}

/** What a gate is evaluated against. */
export interface PullRequestFacts {
  readonly changedFiles: readonly ChangedFile[];
  readonly labels: readonly string[];
  readonly title: string;
}

export interface MergeGateMatch {
  readonly reason: string;
  /** What made it match, named so the person reading the refusal can see why. */
  readonly evidence: readonly string[];
}

/**
 * Every condition a gate may name.
 *
 * Exported because a contract test used to keep its own copy to compare against the
 * documentation — so adding one here and forgetting the test's array left the condition
 * undocumented with both doc tests still green, which is the gap that test exists to
 * close.
 */
export const CONDITION_KEYS = [
  "files_added",
  "files_removed",
  "files_modified",
  "files_changed",
  "labels",
  "title_matches",
] as const;

const GATE_KEYS = ["reason", "when"] as const;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** Read a condition that is a list of path patterns, checking each one's form. */
function readPatterns(raw: unknown, where: string, problems: string[]): string[] {
  if (raw === undefined) return [];
  if (!Array.isArray(raw)) {
    problems.push(`${where} must be an array of path patterns.`);
    return [];
  }
  if (raw.length === 0) {
    problems.push(`${where} is empty, so it constrains nothing; remove the key instead.`);
    return [];
  }
  const patterns: string[] = [];
  for (const entry of raw) {
    // Checked here rather than left to `pathPatternProblem`'s own `typeof`
    // guard. That guard is unreachable by its own signature, so casting a
    // `number` to `string` to reach it made this reader depend on another
    // module's defensive code through an assertion that says the opposite.
    // `readLabels` below already does it this way.
    if (typeof entry !== "string") {
      problems.push(`${where}: every pattern must be a string; found ${JSON.stringify(entry)}.`);
      continue;
    }
    const problem = pathPatternProblem(entry);
    if (problem) {
      problems.push(`${where}: ${problem}`);
      continue;
    }
    patterns.push(entry.trim());
  }
  return patterns;
}

function readLabels(raw: unknown, where: string, problems: string[]): string[] {
  if (raw === undefined) return [];
  if (!Array.isArray(raw) || raw.some((label) => typeof label !== "string" || label.trim() === "")) {
    problems.push(`${where} must be an array of non-empty label names.`);
    return [];
  }
  if (raw.length === 0) {
    problems.push(`${where} is empty, so it constrains nothing; remove the key instead.`);
    return [];
  }
  return (raw as string[]).map((label) => label.trim());
}

function readTitleMatches(raw: unknown, where: string, problems: string[]): string {
  if (raw === undefined) return "";
  if (typeof raw !== "string" || raw.trim() === "") {
    problems.push(`${where} must be a non-empty regular expression.`);
    return "";
  }
  try {
    new RegExp(raw, "i");
  } catch (error) {
    problems.push(`${where} is not a valid regular expression: ${(error as Error).message}`);
    return "";
  }
  return raw;
}

function constrainsAnything(when: MergeGateConditions): boolean {
  return (
    when.filesAdded.length > 0 ||
    when.filesRemoved.length > 0 ||
    when.filesModified.length > 0 ||
    when.filesChanged.length > 0 ||
    when.labels.length > 0 ||
    when.titleMatches !== ""
  );
}

/**
 * Validate `merge_gates`.
 *
 * All or nothing, for the same reason `resolveDeployTargets` is: a partly
 * honoured gate list reports that the gates ran while the one that mattered was
 * dropped. The caller turns any problem into a blocker, so an unusable
 * declaration stops the merge instead of being skipped.
 */
export function resolveMergeGates(raw: unknown): MergeGatesResolution {
  if (raw === undefined || raw === null) return { gates: [], problems: [] };
  if (!Array.isArray(raw)) {
    return { gates: [], problems: ["`merge_gates` must be an array of gate objects."] };
  }

  const problems: string[] = [];
  const gates: MergeGate[] = [];

  raw.forEach((entry, index) => {
    const where = `\`merge_gates[${index}]\``;
    if (!isRecord(entry)) {
      problems.push(`${where} must be an object with \`reason\` and \`when\`.`);
      return;
    }

    for (const key of Object.keys(entry)) {
      if (!(GATE_KEYS as readonly string[]).includes(key)) {
        problems.push(`${where}: unknown key \`${key}\`; a gate has \`reason\` and \`when\`.`);
      }
    }

    const reason = typeof entry.reason === "string" ? entry.reason.trim() : "";
    if (reason === "") {
      problems.push(`${where}: \`reason\` must say why a person should merge this, in their words.`);
    }

    if (!isRecord(entry.when)) {
      problems.push(
        `${where}: \`when\` must be an object naming at least one condition ` +
          `(${CONDITION_KEYS.join(", ")}).`,
      );
      return;
    }
    const declared = entry.when;

    for (const key of Object.keys(declared)) {
      if (!(CONDITION_KEYS as readonly string[]).includes(key)) {
        problems.push(
          `${where}: unknown condition \`${key}\`. A misspelled condition matches nothing, which ` +
            `looks exactly like a gate nobody needed -- so it is an error rather than a no-op. ` +
            `Known conditions: ${CONDITION_KEYS.join(", ")}.`,
        );
      }
    }

    const when: MergeGateConditions = {
      filesAdded: readPatterns(declared.files_added, `${where}.when.files_added`, problems),
      filesRemoved: readPatterns(declared.files_removed, `${where}.when.files_removed`, problems),
      filesModified: readPatterns(declared.files_modified, `${where}.when.files_modified`, problems),
      filesChanged: readPatterns(declared.files_changed, `${where}.when.files_changed`, problems),
      labels: readLabels(declared.labels, `${where}.when.labels`, problems),
      titleMatches: readTitleMatches(declared.title_matches, `${where}.when.title_matches`, problems),
    };

    // A gate with no conditions would stop every merge. That is already sayable
    // as `merge_policy: "manual"`, and someone who wrote it here meant something
    // narrower and lost it to a typo.
    if (!constrainsAnything(when)) {
      problems.push(
        `${where}: \`when\` names no usable condition, so this gate would stop every merge. ` +
          `Set \`merge_policy\` to "manual" if that is the intent.`,
      );
      return;
    }

    gates.push({ reason, when });
  });

  return problems.length > 0 ? { gates: [], problems } : { gates, problems };
}

const ALL_STATUSES: readonly FileStatus[] = ["added", "removed", "modified"];

/** Files with one of `statuses` that any of `patterns` claims. */
function filesMatching(
  files: readonly ChangedFile[],
  statuses: readonly FileStatus[],
  patterns: readonly string[],
): string[] {
  if (patterns.length === 0) return [];
  return files
    .filter((file) => statuses.includes(file.status))
    .filter((file) => patterns.some((pattern) => pathMatches(file.path, pattern)))
    .map((file) => file.path);
}

/**
 * The gates that apply to this pull request, in declared order.
 *
 * A condition that is present and does not hold rules the gate out; a condition
 * that is absent is not consulted. So a gate naming both `files_added` and
 * `labels` applies only to a pull request that does both, and the evidence names
 * what satisfied each part.
 */
export function matchMergeGates(
  gates: readonly MergeGate[],
  facts: PullRequestFacts,
): readonly MergeGateMatch[] {
  const matches: MergeGateMatch[] = [];

  for (const gate of gates) {
    const { when } = gate;
    const evidence: string[] = [];

    const fileConditions: { patterns: readonly string[]; statuses: readonly FileStatus[] }[] = [
      { patterns: when.filesAdded, statuses: ["added"] },
      { patterns: when.filesRemoved, statuses: ["removed"] },
      { patterns: when.filesModified, statuses: ["modified"] },
      { patterns: when.filesChanged, statuses: ALL_STATUSES },
    ];

    let applies = true;
    for (const condition of fileConditions) {
      if (condition.patterns.length === 0) continue;
      const hits = filesMatching(facts.changedFiles, condition.statuses, condition.patterns);
      if (hits.length === 0) {
        applies = false;
        break;
      }
      evidence.push(...hits);
    }
    if (!applies) continue;

    if (when.labels.length > 0) {
      const hits = facts.labels.filter((label) => when.labels.includes(label));
      if (hits.length === 0) continue;
      evidence.push(...hits.map((label) => `label:${label}`));
    }

    if (when.titleMatches !== "") {
      if (!new RegExp(when.titleMatches, "i").test(facts.title)) continue;
      evidence.push(`title:${facts.title}`);
    }

    matches.push({ reason: gate.reason, evidence });
  }

  return matches;
}

/**
 * merge-readiness.ts — decides whether a pull request may be merged, and says
 * why not when it may not.
 *
 * The verdict comes from the repository's own branch protection, not from an
 * opinion held here. GitHub computes `mergeStateStatus` against whatever the
 * active ruleset requires, and the ruleset is a reviewed file
 * (`.github/atoma/rulesets/*.json`), so changing what "mergeable" means is a change to
 * that file — this module and the tools built on it follow automatically, with no
 * second definition to keep in step.
 *
 * That matters because the previous version WAS a second definition: it decided
 * on its own that checks must be green and conflicts absent. Anything the
 * repository required but this file did not know about went unenforced, and it
 * governed only the agent path — a person merging from the GitHub UI walked past
 * it entirely. Protection now applies to both, and this reports it.
 *
 * The remaining local input is `merge_policy`, which is Atoma's own concept and
 * has no GitHub equivalent.
 */

import type { MergeGateMatch } from "./merge-gates.ts";
import { pathMatches } from "./path-patterns.ts";

/** A single check run, reduced to what reporting needs. */
export interface CheckRun {
  name: string;
  /** GitHub `status`: queued | in_progress | completed. */
  status: string;
  /** GitHub `conclusion`, null while incomplete. */
  conclusion: string | null;
  detailsUrl?: string;
}

export interface MergeSignals {
  /**
   * GitHub's computed merge state, evaluated against the active ruleset:
   * CLEAN | BLOCKED | DIRTY | BEHIND | UNSTABLE | DRAFT | HAS_HOOKS | UNKNOWN.
   * This is the verdict; everything else here only explains it.
   */
  mergeStateStatus: string;
  state: string;
  /**
   * Whether the pull request is a draft, read from the pull request itself.
   *
   * Not derived from `mergeStateStatus`. GitHub documents `DRAFT` as one of its
   * values, but reports `CLEAN` for a draft in practice, so the `DRAFT` case below
   * never fired and a draft was reported ready to merge. `isDraft` is an attribute
   * of the pull request rather than a computed verdict, so it does not move.
   */
  isDraft: boolean;
  /**
   * Whether the pull request was opened by an agent rather than by a person.
   *
   * Read from the author's type, not from a name, so it does not depend on which
   * identity a deployment runs under.
   *
   * `merge_policy` bounds how much an agent decides on its own, and the work it
   * was meant to bound is the agent's own. A person opening a pull request is
   * proposing something and asking what a reviewer makes of it; merging it for
   * them takes that decision away, and does it before they have read the review.
   * So the policy applies to agent-authored pull requests, and a person's own
   * stays theirs to merge.
   */
  authoredByAgent: boolean;
  /** Check runs on the head commit, used to name what is failing or pending. */
  checks: CheckRun[];
  /**
   * Status check contexts the ruleset requires, from
   * `GET /repos/{owner}/{repo}/rules/branches/{branch}`. Empty when the branch
   * has no such rule.
   */
  requiredChecks: string[];
  /** `merge_policy` from config.json. Atoma's own gate, not GitHub's. */
  mergePolicy: string;
  /**
   * Paths this pull request changes that govern how agents run — workflows,
   * agent definitions, tool configuration, rulesets.
   *
   * Empty for ordinary work, which is nearly every pull request. Non-empty means
   * the change alters the machinery that decides what an agent may do, including
   * the parts that hold credentials and the parts that gate this very merge.
   */
  governancePaths: string[];
  /**
   * Why the changed-file list could not be read, when it could not.
   *
   * Absent means it was read; `governancePaths` above is then the answer, empty
   * or not. Present means there is no answer, and the two must not share a
   * representation — `merge-signals.ts` used to put the literal string
   * `"(could not read the changed files)"` into `governancePaths`, which
   * produced the refusal "this pull request changes how agents themselves run
   * ((could not read the changed files))". The blocking was right. The sentence
   * was false: the pull request may change nothing of the sort, and what is
   * actually true is that nobody knows.
   */
  governanceUnknown?: string;
  /**
   * Gates from `merge_gates` that apply to this pull request.
   *
   * The project's own conditions, not Atoma's. `governancePaths` above is the one
   * Atoma declares for itself; these are whatever an adopter wanted kept out of
   * an agent's hands — a migration, a release note, a labelled change — said in
   * configuration rather than in code here.
   */
  gateMatches: MergeGateMatch[];
  /**
   * Why a declared gate could not be evaluated.
   *
   * Non-empty blocks. A gate that could not be read has not said yes, and the
   * whole point of declaring one is that the merge stops when it applies — so an
   * unusable declaration must not come to the same thing as no declaration.
   */
  gateProblems: string[];
}

export type BlockerKind =
  | "not-open"
  | "draft"
  | "conflicting"
  | "behind"
  | "blocked"
  | "checks-missing"
  | "checks-pending"
  | "checks-failing"
  | "mergeability-unknown"
  | "merge-policy"
  | "human-authored"
  | "governance-change"
  | "merge-gate"
  | "gate-config-invalid"
  | "governance-unknown";

export interface Blocker {
  kind: BlockerKind;
  /** One line an agent can act on or relay to a human. */
  detail: string;
}

/**
 * Blockers that mean this head commit is going to change, so a CI run started
 * against it would be thrown away.
 *
 * `needsCiDispatch` is the recovery path for a required check that never got
 * written -- the normal path is `create_pr` and `commit_and_push` dispatching
 * validation, and this exists for when that did not happen. It fires when a
 * check is missing and nothing in this list is in the way.
 *
 * It used to fire only when `checks-missing` was the sole blocker, which is a
 * different and much narrower rule: `merge_policy` defaults to `"manual"`, and
 * that adds a `merge-policy` blocker to every pull request. So on any project
 * using the default -- most of them -- the recovery path could never run at all,
 * and the person who has to do the merge was left waiting on a required check
 * that nothing was going to create.
 *
 * The rule is now about the commit rather than about the merge. `merge-policy`,
 * `human-authored`, `governance-change`, `merge-gate`, `gate-config-invalid`,
 * `governance-unknown` and `blocked` all stop the agent from merging and leave
 * the head commit exactly as it is -- so the check is still needed, and still
 * worth writing, by whoever ends up merging. The kinds below are the ones where
 * it is not: the commit must change first, or there is nothing to validate.
 *
 * `checks-pending` and `checks-failing` are here for the other reason: a run
 * already exists for this commit, so starting a second one duplicates it.
 */
const CI_WOULD_BE_WASTED: ReadonlySet<BlockerKind> = new Set([
  "not-open",
  "draft",
  "conflicting",
  "behind",
  "mergeability-unknown",
  "checks-pending",
  "checks-failing",
]);

export interface MergeReadiness {
  ready: boolean;
  blockers: Blocker[];
  /** True when a required check has never run on the head commit. */
  needsCiDispatch: boolean;
}

/** Conclusions that satisfy a required check. Skipped and neutral are not failures. */
const PASSING = new Set(["success", "neutral", "skipped"]);

/**
 * The deployed files that decide how an agent runs, and so what it may reach.
 *
 * Deployed paths, not source paths: this is what an adopter's repository looks
 * like. A template repository developing the same files under `src/` is doing
 * ordinary work on ordinary files, and adds its own patterns if it wants them
 * covered.
 *
 * One pattern rather than a list of the directories that matter, because the
 * list was wrong. It named `workflows`, `actions`, `atoma` and `rulesets` and
 * omitted `.github/scripts/**` — where the runner's own control logic lives, run
 * by a job holding `contents: write`, `issues: write`, `pull-requests: write`
 * and `actions: write`. An agent could rewrite the rule releasing the
 * in-progress guard, or the auto-dispatch loop limit, and merge it unreviewed.
 *
 * Nothing chose that; enumerating did. `.github/scripts/` arrived after the list
 * was written and nobody added it. A list of exceptions has to be revisited every
 * time the tree grows, and it silently fails when it is not — so this covers the
 * directory and lets a project narrow it, rather than naming parts and hoping the
 * next addition is noticed.
 *
 * It reaches a few files that are not an agent's limits — `dependabot.yml`,
 * `CODEOWNERS`, issue templates. Those change rarely, and the first two are
 * things a person should see change anyway.
 */
export const DEFAULT_GOVERNED_PATHS = [".github/**"] as const;

/** A file whose changer probably meant to change what CI or a deployment does. */
function isGeneratedWorkflow(path: string): boolean {
  return path.startsWith(".github/workflows/");
}

/**
 * Which of `files` a pattern claims.
 *
 * The matcher itself moved to `path-patterns.ts`, which explains the one pattern
 * form Atoma accepts and why. `merge_gates` needed the same comparison, and two
 * copies of a security-shaped one is the arrangement that drifts.
 */
export function governedPathsIn(files: string[], patterns: readonly string[]): string[] {
  return files.filter((file) => patterns.some((pattern) => pathMatches(file, pattern)));
}

/**
 * Explain a BLOCKED verdict in terms of the required checks, so a refusal names
 * the check to fix rather than restating that GitHub said no.
 */
function explainRequiredChecks(signals: MergeSignals): Blocker[] {
  const blockers: Blocker[] = [];
  const byName = new Map(signals.checks.map((c) => [c.name, c]));

  for (const context of signals.requiredChecks) {
    const run = byName.get(context);
    if (!run) {
      blockers.push({
        kind: "checks-missing",
        detail: `required check "${context}" has not run on the head commit`,
      });
    } else if (run.status !== "completed") {
      blockers.push({
        kind: "checks-pending",
        detail: `required check "${context}" is ${run.status}`,
      });
    } else if (!PASSING.has((run.conclusion ?? "").toLowerCase())) {
      const where = run.detailsUrl ? ` (${run.detailsUrl})` : "";
      blockers.push({
        kind: "checks-failing",
        detail: `required check "${context}" concluded ${run.conclusion}${where}`,
      });
    }
  }
  return blockers;
}

export function decideMergeReadiness(signals: MergeSignals): MergeReadiness {
  const blockers: Blocker[] = [];

  if (signals.state?.toUpperCase() !== "OPEN") {
    blockers.push({ kind: "not-open", detail: `pull request state is ${signals.state}, not OPEN` });
  }

  // Before the verdict, because the verdict does not carry this. GitHub reports
  // `CLEAN` for a draft, so relying on the `DRAFT` case below reported a draft as
  // ready and left the refusal to come back from the merge call as a raw API error
  // no blocker kind described.
  if (signals.isDraft) {
    blockers.push({ kind: "draft", detail: "pull request is a draft; mark it ready for review first" });
  }

  switch (signals.mergeStateStatus?.toUpperCase()) {
    case "CLEAN":
    case "UNSTABLE": // a non-required check is failing; the ruleset permits merging
      break;
    case "DRAFT":
      // Kept although `isDraft` above already covers it, so this does not break if
      // GitHub starts returning the value its own docs list. Guarded to avoid
      // reporting the same blocker twice when it does.
      if (!signals.isDraft) {
        blockers.push({ kind: "draft", detail: "pull request is a draft; mark it ready for review first" });
      }
      break;
    case "DIRTY":
      blockers.push({
        kind: "conflicting",
        detail: "branch conflicts with the base; call github__sync_branch and resolve before merging",
      });
      break;
    case "BEHIND":
      blockers.push({
        kind: "behind",
        detail: "branch is behind the base and the ruleset requires it current; call github__sync_branch",
      });
      break;
    case "BLOCKED": {
      // Blocked by branch protection. Name the specific required checks when we
      // can; fall back to the raw verdict when the cause is something else the
      // ruleset requires (a review, an unresolved thread).
      const explained = explainRequiredChecks(signals);
      if (explained.length > 0) blockers.push(...explained);
      else
        blockers.push({
          kind: "blocked",
          detail:
            "branch protection blocks this merge for a reason outside the required checks " +
            "(for example a required review or an unresolved conversation); inspect the pull request",
        });
      break;
    }
    default:
      blockers.push({
        kind: "mergeability-unknown",
        detail: `GitHub reports mergeStateStatus=${signals.mergeStateStatus ?? "null"}; retry shortly`,
      });
  }

  // A person's pull request is theirs to merge, whatever the policy says. They
  // opened it to hear what a reviewer makes of it, and merging it for them ends
  // that before they have read the answer.
  if (!signals.authoredByAgent) {
    blockers.push({
      kind: "human-authored",
      detail: "a person opened this pull request; review it and report, but leave the merge to them",
    });
  }

  if (signals.mergePolicy !== "auto") {
    blockers.push({
      kind: "merge-policy",
      detail: `merge_policy is '${signals.mergePolicy}', not 'auto'; a human performs the merge`,
    });
  }

  // Every other gate here is something an agent may satisfy and then merge. This
  // one it may not, because the change would alter the gates themselves.
  //
  // Workflows, agent definitions, tool configuration and rulesets are where an
  // agent's limits live — which credentials reach a run, which commands a hook
  // refuses, what a ruleset requires before a merge. An agent that can merge a
  // change to those can widen its own reach, and no later check catches it: the
  // next run already obeys the new file.
  //
  // Not a suspicion that an agent means to. A prompt injection carried in an
  // issue body, or a plain mistake, reaches just as far, and both stop at a
  // person reading the diff.
  // Same fail-closed outcome as the gate below, with a true sentence. The
  // changed files are what decides whether this touches governance, so not
  // having them means the question is open, and an open question about the
  // machinery agents run on is a person's to close.
  if (signals.governanceUnknown) {
    blockers.push({
      kind: "governance-unknown",
      detail:
        "whether this pull request changes how agents themselves run could not be determined " +
        `(${signals.governanceUnknown}), so the merge falls to a person`,
    });
  }

  if (signals.governancePaths.length > 0) {
    const shown = signals.governancePaths.slice(0, 5).join(", ");
    const rest = signals.governancePaths.length - 5;
    blockers.push({
      kind: "governance-change",
      detail:
        `this pull request changes how agents themselves run (${shown}${rest > 0 ? `, +${rest} more` : ""}); ` +
        "review it and report, but leave the merge to a person" +
        // Said here because this is the moment someone is looking. The commonest
        // reason to touch a generated workflow is to change what CI or a
        // deployment does, and under Atoma that is not where those live -- so
        // name the place it does live rather than only refusing the merge.
        (signals.governancePaths.some(isGeneratedWorkflow)
          ? ". If the intent was to change what CI or deployment does, that belongs in " +
            "`.github/atoma/config.json` (`checks.commands`, `deploy.targets`) rather than in a " +
            "workflow file — an agent can write config and cannot write a workflow. If this is an " +
            "upgrade of the generated deliverable, it is exactly what a person should be merging"
          : ""),
    });
  }

  // The project's own version of the gate above. Same shape, same outcome — the
  // agent reviews and reports, a person merges — but the condition comes from
  // `merge_gates` in config.json rather than from this file, because what must
  // not be merged unread is a property of the project and not of Atoma. A
  // migration, a change to a pricing table, a release note: nothing here could
  // have guessed them.
  //
  // The reason is relayed verbatim, in whatever language it was written in. It is
  // addressed to the person who will merge, and they wrote it.
  for (const match of signals.gateMatches) {
    const shown = match.evidence.slice(0, 5).join(", ");
    const rest = match.evidence.length - 5;
    const because = shown ? ` (matched ${shown}${rest > 0 ? `, +${rest} more` : ""})` : "";
    blockers.push({
      kind: "merge-gate",
      detail:
        `a merge gate declared by this project applies${because}: ${match.reason}` +
        " — review it and report, but leave the merge to a person",
    });
  }

  // Fail closed. An unreadable gate is the case this whole mechanism exists for:
  // if a broken declaration merely disappeared, the way to merge past a gate
  // would be to break it, and the diff that breaks it would be merged by the
  // agent the gate was meant to stop.
  for (const problem of signals.gateProblems) {
    blockers.push({
      kind: "gate-config-invalid",
      detail:
        `a declared merge gate could not be evaluated, so this merge falls to a person: ${problem}`,
    });
  }

  const needsCiDispatch =
    blockers.some((b) => b.kind === "checks-missing") && !blockers.some((b) => CI_WOULD_BE_WASTED.has(b.kind));

  return { ready: blockers.length === 0, blockers, needsCiDispatch };
}

/** Render blockers as a numbered list for a tool result or an issue comment. */
export function formatBlockers(blockers: Blocker[]): string {
  return blockers.map((b, i) => `${i + 1}. [${b.kind}] ${b.detail}`).join("\n");
}

